 "content": "def transform(grid):
    """Expand a single marker into a V of 2s and a periodic diagonal field of 1s."""
    width = len(grid[0])
    marker = next(c for c, value in enumerate(grid[0]) if value == 2)
    height = width
    out = [[0] * width for _ in range(height)]

    # The marker sends two diagonal arms down and outward.
    for r in range(height):
        for c in (marker - r, marker + r):
            if 0 <= c < width:
                out[r][c] = 2

    # Below the initial region, parallel diagonals repeat every four columns.
    start_r = marker // 2
    start_c = marker - 1
    phase = (start_c - start_r) % 4
    for r in range(start_r, height):
        for c in range(width):
            if (c - r) % 4 == phase and out[r][c] == 0:
                out[r][c] = 1
    return out
